import {BROKE_DESIGN_PREVIEW_ENABLED} from './dev-preview.mjs';
let designPreview=false;
const previewUser={id:'broke-design-preview',name:'Broke · Xây dựng',role:'Broke',emailVerified:false,designPreview:true};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let signupRole='Broke';let api,mode='signup',requestData=null,challenge=null,configured=false,onSuccess,timer;
async function call(path,data){const r=await fetch('/api/auth/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'Không thể kết nối máy chủ.');return result;}
export function initRegistration(callbacks){api=callbacks;const root=document.createElement('section');root.id='registration-page';document.body.append(root);}
export async function requireRegistration(success,role='Broke'){signupRole=role;onSuccess=success;if(role==='Broke'&&BROKE_DESIGN_PREVIEW_ENABLED&&designPreview){success(previewUser);return;}try{const {user}=await call('me');if(user?.emailVerified){success(user);return;}}catch{}show();}
async function show(){clearInterval(timer);mode='signup';challenge=null;requestData=null;configured=false;document.body.classList.remove('onboarding','broke-mode','messages-mode','debts-mode');document.body.classList.add('registration-mode');render();try{configured=(await call('config')).emailConfigured;}catch{}if(document.body.classList.contains('registration-mode'))render();window.scrollTo(0,0);}
function render(){document.querySelector('#registration-page').innerHTML=`<div class="registration-top"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"><button id="registration-back">← Quay lại</button></div><div class="registration-layout"><section class="registration-intro"><div class="registration-mark"><img src="assets/debtfreelately-mark-clean.png" alt=""></div><p class="registration-eyebrow">A LITTLE HELP. A FRESH START.</p><h1>Bạn không cần<br>đi một mình.</h1><p>Một tài khoản, một khởi đầu mới.<br>Để câu chuyện của bạn được lắng nghe.</p><div class="registration-steps"><div class="${challenge?'done':'current'}"><b>1</b><span>Thông tin của bạn</span></div><i></i><div class="${challenge?'current':''}"><b>2</b><span>Xác nhận email</span></div><i></i><div><b>3</b><span>Bắt đầu hành trình</span></div></div><small>Tên thật, số điện thoại và email dùng cho tài khoản,<br>không được đưa lên thẻ câu chuyện công khai.</small></section><section class="registration-card"><p class="registration-eyebrow">${challenge?'VERIFY YOUR EMAIL':mode==='login'?'WELCOME BACK':'WELCOME, BROKE'}</p><h2>${challenge?'Kiểm tra hộp thư của bạn':mode==='login'?'Chào mừng trở lại.':'Bắt đầu hành trình mới.'}</h2><p class="registration-subtitle">${challenge?`Nhập mã 6 chữ số đã gửi tới <strong>${esc(requestData.email)}</strong>.`:mode==='login'?'Đăng nhập bằng mã gửi qua email, không cần mật khẩu.':'Tạo tài khoản Broke để chia sẻ và quản lý hành trình của bạn.'}</p>${!configured?'<div class="registration-notice" role="status"><strong>Đang chuẩn bị dịch vụ email</strong><span>Chưa thể gửi mã hoặc tạo tài khoản. Form đã sẵn sàng; cần cấu hình dịch vụ gửi email ở máy chủ.</span></div>':''}<form id="registration-form">${challenge?'<label for="reg-code">Mã xác nhận email</label><input id="reg-code" name="code" class="otp-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required placeholder="000000"><p class="registration-caption">Mã có hiệu lực 10 phút và tối đa 5 lần thử.</p>':`${mode==='signup'?'<label for="reg-name">Họ và tên thật</label><input id="reg-name" name="name" autocomplete="name" minlength="2" maxlength="100" required placeholder="Nhập đầy đủ họ và tên"><div class="registration-two"><div><label for="reg-gender">Giới tính</label><select id="reg-gender" name="gender" required><option value="">Chọn giới tính</option value="female">Nữ</option><option value="male">Nam</option><option value="other">Khác</option><option value="undisclosed">Không muốn tiết lộ</option></select></div><div><label for="reg-age">Tuổi</label><input id="reg-age" name="age" type="number" min="1" max="120" step="1" required placeholder="Tuổi của bạn"></div></div><label for="reg-phone">Số điện thoại</label><input id="reg-phone" name="phone" type="tel" autocomplete="tel" maxlength="25" required placeholder="Ví dụ: +84 912 345 678">':''}<label for="reg-email">Địa chỉ email</label><input id="reg-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="ban@example.com"><p class="registration-caption">Chúng mình sẽ gửi mã để xác nhận email thuộc về bạn.</p>`}<p id="registration-error" class="form-error" role="alert"></p><button class="registration-submit" ${configured?'':'disabled'}>${challenge?'Xác nhận và tiếp tục':'Gửi mã xác nhận email'} <span>→</span></button></form>${challenge?'<button class="registration-alt" id="reg-resend" disabled>Gửi lại mã sau 60 giây</button><button class="registration-alt" id="reg-change">Đổi email / nhập lại thông tin</button>':`<div class="registration-switch">${mode==='signup'?'Đã có tài khoản?':'Chưa có tài khoản?'} <button id="registration-mode">${mode==='signup'?'Đăng nhập':'Đăng ký Broke'}</button></div>`}<p class="registration-footnote">Chỉ sau khi xác nhận đúng mã, tài khoản mới được tạo.<br>Không có thanh toán trong bước đăng ký.</p></section></div>`;
if(signupRole==='Bros'&&!challenge&&mode==='signup'){document.querySelector('.registration-card .registration-eyebrow').textContent='WELCOME, BROS';document.querySelector('.registration-subtitle').textContent='Tạo tài khoản Bros với thông tin đầy đủ và xác minh email.';}if(signupRole==='Bros'&&mode==='login'&&!challenge)document.querySelector('#registration-mode').textContent='Đăng ký Bros';
if(signupRole==='Broke'&&BROKE_DESIGN_PREVIEW_ENABLED){const shortcut=document.createElement('button');shortcut.type='button';shortcut.className='registration-preview';shortcut.textContent='Bỏ qua đăng ký · Chế độ xây dựng →';shortcut.onclick=()=>{clearInterval(timer);requestData=null;challenge=null;designPreview=true;document.body.classList.remove('registration-mode');onSuccess(previewUser);api.toast('Đang xem thử giao diện. Chưa tạo tài khoản hoặc xác minh email.');};document.querySelector('.registration-card').append(shortcut);}
document.querySelector('#registration-back').onclick=()=>{clearInterval(timer);requestData=null;challenge=null;document.body.classList.remove('registration-mode');api.back();};document.querySelector('#registration-mode')?.addEventListener('click',()=>{mode=mode==='signup'?'login':'signup';render();});document.querySelector('#reg-change')?.addEventListener('click',()=>{clearInterval(timer);challenge=null;requestData=null;render();});document.querySelector('#reg-resend')?.addEventListener('click',async()=>{const b=document.querySelector('#reg-resend');b.disabled=true;try{challenge=await call('request-code',requestData);countdown();api.toast('Đã yêu cầu gửi mã mới. Vui lòng kiểm tra hộp thư.');}catch(error){document.querySelector('#registration-error').textContent=error.message;b.disabled=false;}});
document.querySelector('#registration-form').onsubmit=async ev=>{ev.preventDefault();if(!configured)return;const submit=ev.target.querySelector('button');submit.disabled=true;document.querySelector('#registration-error').textContent='';try{if(challenge){const {user}=await call('verify-code',{id:challenge.id,code:new FormData(ev.target).get('code')});clearInterval(timer);requestData=null;challenge=null;document.body.classList.remove('registration-mode');onSuccess(user);api.toast('Email đã được xác minh. Chào mừng bạn!');}else{requestData={...Object.fromEntries(new FormData(ev.target)),purpose:mode,role:signupRole};challenge=await call('request-code',requestData);render();countdown();document.querySelector('#reg-code').focus();}}catch(error){document.querySelector('#registration-error').textContent=error.message;submit.disabled=false;}};
}
function countdown(){clearInterval(timer);const until=Date.now()+60000;function tick(){const button=document.querySelector('#reg-resend');if(!button){clearInterval(timer);return;}const seconds=Math.max(0,Math.ceil((until-Date.now())/1000));button.disabled=seconds>0;button.textContent=seconds?`Gửi lại mã sau ${seconds} giây`:'Gửi lại mã';if(!seconds)clearInterval(timer);}tick();timer=setInterval(tick,1000);}
export async function logoutRegistration(){designPreview=false;try{await call('logout',{});api.back();}catch{api.toast('Không thể đăng xuất. Vui lòng thử lại.');}}



